"use client"

import { motion } from "framer-motion"
import { ExternalLink, Github, ArrowUpRight } from "lucide-react"
import { Badge } from "@/components/ui/badge"

interface ProjectCardProps {
  title: string
  description: string
  image: string
  tags: string[]
  githubUrl: string
  liveUrl: string
  role?: string
}

export function ProjectCard({ title, description, image, tags, githubUrl, liveUrl, role }: ProjectCardProps) {
  return (
    <motion.div
      whileHover={{ y: -5, rotateX: 5, rotateY: 5, scale: 1.02 }}
      transition={{ type: "spring", stiffness: 300, damping: 20 }}
      style={{ perspective: 1000 }}
      className="group relative bg-[#FAFAF5] dark:bg-card p-4 pb-6 shadow-[0_10px_30px_rgba(0,0,0,0.05)] hover:shadow-[0_20px_40px_rgba(var(--primary-rgb),0.15)] border border-muted/50 transition-all duration-500 w-full max-w-sm mx-auto"
    >
      {/* Tape effect on top */}
      <div className="absolute -top-3 left-1/2 -translate-x-1/2 w-16 h-6 bg-primary/20 backdrop-blur-sm -rotate-2 z-20 mix-blend-multiply" />

      {/* Image Frame (Polaroid style) */}
      <div className="relative aspect-[4/3] mb-6 overflow-hidden border border-border bg-muted/30">
        {/* Overlay envelhecido que some no hover */}
        <div className="absolute inset-0 bg-[#D4A373]/20 mix-blend-color z-10 group-hover:opacity-0 transition-opacity duration-700 pointer-events-none" />
        <div className="absolute inset-0 bg-primary/10 mix-blend-multiply z-10 group-hover:opacity-0 transition-opacity duration-700 pointer-events-none" />
        
        <img
          src={image || "/placeholder.svg"}
          alt={title}
          className="object-cover w-full h-full grayscale sepia-[0.3] contrast-75 group-hover:grayscale-0 group-hover:sepia-0 group-hover:contrast-100 group-hover:scale-110 transition-all duration-700 ease-out"
        />

        {/* Floating Links inside image */}
        <div className="absolute top-4 right-4 z-20 flex gap-2 opacity-0 -translate-y-2 group-hover:opacity-100 group-hover:translate-y-0 transition-all duration-500">
          {githubUrl !== "#" && (
            <a
              href={githubUrl}
              target="_blank"
              rel="noopener noreferrer"
              className="p-2 bg-background/90 backdrop-blur-sm text-foreground hover:text-primary transition-colors border border-border"
            >
              <Github className="h-4 w-4" />
            </a>
          )}
          {liveUrl !== "#" && (
            <a
              href={liveUrl}
              target="_blank"
              rel="noopener noreferrer"
              className="p-2 bg-background/90 backdrop-blur-sm text-foreground hover:text-primary transition-colors border border-border"
            >
              <ExternalLink className="h-4 w-4" />
            </a>
          )}
        </div>
      </div>

      {/* Role / Tag minimalista */}
      {role && (
        <p className="text-xs font-bold uppercase tracking-widest text-primary mb-2">
          {role}
        </p>
      )}

      {/* Title */}
      <h3 className="text-2xl font-serif italic text-foreground mb-3 group-hover:text-primary transition-colors flex justify-between items-center">
        {title}
        <ArrowUpRight className="h-5 w-5 opacity-0 -translate-x-2 translate-y-2 group-hover:opacity-100 group-hover:translate-x-0 group-hover:-translate-y-0 transition-all duration-500 text-primary" />
      </h3>
      
      <p className="text-sm text-muted-foreground font-sans leading-relaxed mb-6">
        {description}
      </p>

      {/* Tags Line */}
      <div className="flex flex-wrap gap-2 pt-4 border-t border-border/50">
        {tags.map((tag) => (
          <span 
            key={tag}
            className="text-[10px] font-medium uppercase tracking-wider text-foreground/70 bg-muted px-2 py-1"
          >
            {tag}
          </span>
        ))}
      </div>
    </motion.div>
  )
}
